  root.addEventListener('submit',async event=>{event.preventDefault();if(event.target.id==='identity-form')await verifyIdentity(event.target);if(event.target.id==='auth-form')await authenticate(event.target);if(event.target.id==='message-form'){if(state.messagingProviderConnected)await sendMessage();else await saveMessageDraft();}if(event.target.id==='import-form'){const value=document.getElementById('import-orders').value.trim();const ids=value.split(/[\s,]+/).filter(Boolean);if(!ids.length||ids.some(id=>!/^\d+$/.test(id))){state.error='Enter valid order IDs, separated by commas.';render();return;}await syncOrders([...new Set(ids)]);}});
